using DesignStore.Domain.Commerce;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DesignStore.Infrastructure.Persistence;

internal static class CommerceConfigurationExtensions
{
    public static void Money<T>(this EntityTypeBuilder<T> b, params string[] names) where T : class { foreach (var n in names) b.Property<decimal>(n).HasPrecision(18, 2); }
    public static void Audit<T>(this EntityTypeBuilder<T> b) where T : class { b.Property("CreatedAtUtc").HasColumnType("timestamp with time zone"); }
    /// <summary>Optimistic concurrency via the PostgreSQL system column xmin (shadow property, no extra column).</summary>
    public static void ConcurrencyToken<T>(this EntityTypeBuilder<T> b) where T : class { b.Property<uint>("Version").IsRowVersion(); }
}
public sealed class CartConfiguration : IEntityTypeConfiguration<Cart> { public void Configure(EntityTypeBuilder<Cart> b) { b.HasIndex(x => x.TokenHash).IsUnique(); b.HasIndex(x => x.UserId); b.Property(x => x.TokenHash).HasMaxLength(64); b.Property(x => x.Culture).HasMaxLength(10); b.Property(x => x.Currency).HasMaxLength(3); b.Property(x => x.DiscountCode).HasMaxLength(50); b.HasMany(x => x.Items).WithOne(x => x.Cart).HasForeignKey(x => x.CartId).OnDelete(DeleteBehavior.Cascade); } }
public sealed class CartItemConfigurationMap : IEntityTypeConfiguration<CartItem> { public void Configure(EntityTypeBuilder<CartItem> b) { b.HasIndex(x => new { x.CartId, x.ProductId, x.ProductVariantId, x.ConfigurationFingerprint }).IsUnique(); b.Property(x => x.ConfigurationFingerprint).HasMaxLength(64); b.Property(x => x.LastUnitPrice).HasPrecision(18, 2); b.HasOne(x => x.Product).WithMany().HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.ProductVariant).WithMany().HasForeignKey(x => x.ProductVariantId).OnDelete(DeleteBehavior.Restrict); b.HasMany(x => x.Configuration).WithOne(x => x.CartItem).HasForeignKey(x => x.CartItemId).OnDelete(DeleteBehavior.Cascade); b.ToTable(t => t.HasCheckConstraint("CK_CartItem_Quantity", "\"Quantity\" > 0")); } }
public sealed class CartItemConfigurationConfiguration : IEntityTypeConfiguration<CartItemConfiguration> { public void Configure(EntityTypeBuilder<CartItemConfiguration> b) { b.Property(x => x.CustomText).HasMaxLength(500); b.Property(x => x.PriceAdjustment).HasPrecision(18, 2); b.HasIndex(x => new { x.CartItemId, x.ProductOptionId }).IsUnique(); } }
public sealed class OrderConfiguration : IEntityTypeConfiguration<Order> { public void Configure(EntityTypeBuilder<Order> b) { b.HasIndex(x => x.Number).IsUnique(); b.HasIndex(x => x.IdempotencyKey).IsUnique(); b.Property(x => x.Number).HasMaxLength(30); b.Property(x => x.IdempotencyKey).HasMaxLength(100); b.Property(x => x.Email).HasMaxLength(320); b.Property(x => x.Currency).HasMaxLength(3); b.Property(x => x.DiscountCode).HasMaxLength(50); b.Property(x => x.ShippingMethod).HasMaxLength(60); b.ConcurrencyToken(); b.Money(nameof(Order.ExchangeRate), nameof(Order.Subtotal), nameof(Order.DiscountTotal), nameof(Order.ShippingTotal), nameof(Order.TaxTotal), nameof(Order.Total)); b.HasMany(x => x.Items).WithOne(x => x.Order).HasForeignKey(x => x.OrderId).OnDelete(DeleteBehavior.Restrict); b.HasMany(x => x.Addresses).WithOne(x => x.Order).HasForeignKey(x => x.OrderId).OnDelete(DeleteBehavior.Restrict); b.HasMany(x => x.StatusHistory).WithOne(x => x.Order).HasForeignKey(x => x.OrderId).OnDelete(DeleteBehavior.Restrict); b.HasMany(x => x.Payments).WithOne(x => x.Order).HasForeignKey(x => x.OrderId).OnDelete(DeleteBehavior.Restrict); } }
public sealed class OrderItemConfigurationMap : IEntityTypeConfiguration<OrderItem> { public void Configure(EntityTypeBuilder<OrderItem> b) { b.Property(x => x.ProductName).HasMaxLength(200); b.Property(x => x.VariantName).HasMaxLength(200); b.Property(x => x.Sku).HasMaxLength(80); b.Property(x => x.ImageUrl).HasMaxLength(500); b.Property(x => x.Currency).HasMaxLength(3); b.Money(nameof(OrderItem.UnitPrice), nameof(OrderItem.DiscountAmount), nameof(OrderItem.VatRate), nameof(OrderItem.TaxAmount), nameof(OrderItem.LineTotal), nameof(OrderItem.ExchangeRate)); b.HasMany(x => x.Configuration).WithOne(x => x.OrderItem).HasForeignKey(x => x.OrderItemId).OnDelete(DeleteBehavior.Restrict); } }
public sealed class OrderItemConfigurationConfiguration : IEntityTypeConfiguration<OrderItemConfiguration> { public void Configure(EntityTypeBuilder<OrderItemConfiguration> b) { b.Property(x => x.OptionName).HasMaxLength(160); b.Property(x => x.Value).HasMaxLength(500); b.Property(x => x.PriceAdjustment).HasPrecision(18, 2); } }
public sealed class OrderAddressConfiguration : IEntityTypeConfiguration<OrderAddress> { public void Configure(EntityTypeBuilder<OrderAddress> b) { b.HasIndex(x => new { x.OrderId, x.Type }).IsUnique(); b.Property(x => x.FullName).HasMaxLength(200); b.Property(x => x.Company).HasMaxLength(200); b.Property(x => x.Street).HasMaxLength(250); b.Property(x => x.City).HasMaxLength(120); b.Property(x => x.PostalCode).HasMaxLength(20); b.Property(x => x.CountryCode).HasMaxLength(2); b.Property(x => x.Phone).HasMaxLength(40); } }
public sealed class OrderStatusHistoryConfiguration : IEntityTypeConfiguration<OrderStatusHistory> { public void Configure(EntityTypeBuilder<OrderStatusHistory> b) { b.HasIndex(x => new { x.OrderId, x.CreatedAtUtc }); b.Property(x => x.Reason).HasMaxLength(500); } }
public sealed class PaymentConfiguration : IEntityTypeConfiguration<Payment> { public void Configure(EntityTypeBuilder<Payment> b) { b.HasIndex(x => x.ExternalEventId).IsUnique().HasFilter("\"ExternalEventId\" <> ''"); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.Currency).HasMaxLength(3); b.Property(x => x.ProviderReference).HasMaxLength(100); b.Property(x => x.ExternalEventId).HasMaxLength(100); } }
public sealed class DiscountCodeConfiguration : IEntityTypeConfiguration<DiscountCode> { public void Configure(EntityTypeBuilder<DiscountCode> b) { b.HasIndex(x => x.Code).IsUnique(); b.Property(x => x.Code).HasMaxLength(50); b.Money(nameof(DiscountCode.Value), nameof(DiscountCode.MinimumOrderValue)); } }
public sealed class InventoryMovementConfiguration : IEntityTypeConfiguration<InventoryMovement> { public void Configure(EntityTypeBuilder<InventoryMovement> b) { b.HasIndex(x => new { x.ProductId, x.ProductVariantId, x.CreatedAtUtc }); b.HasIndex(x => x.OrderId); b.Property(x => x.Reason).HasMaxLength(300); b.ToTable(t => t.HasCheckConstraint("CK_InventoryMovement_Unit", "(\"ProductId\" IS NOT NULL AND \"ProductVariantId\" IS NULL) OR (\"ProductId\" IS NULL AND \"ProductVariantId\" IS NOT NULL)")); } }
public sealed class OutboxMessageConfiguration : IEntityTypeConfiguration<OutboxMessage> { public void Configure(EntityTypeBuilder<OutboxMessage> b) { b.HasIndex(x => new { x.ProcessedAtUtc, x.NextAttemptAtUtc }); b.Property(x => x.Type).HasMaxLength(100); b.Property(x => x.Payload).HasMaxLength(8000); b.Property(x => x.LastError).HasMaxLength(2000); } }
public sealed class ShipmentConfiguration : IEntityTypeConfiguration<Shipment> { public void Configure(EntityTypeBuilder<Shipment> b) { b.HasOne(x => x.Order).WithMany(x => x.Shipments).HasForeignKey(x => x.OrderId).OnDelete(DeleteBehavior.Restrict); b.Property(x => x.Carrier).HasMaxLength(100); b.Property(x => x.Service).HasMaxLength(100); b.Property(x => x.TrackingNumber).HasMaxLength(100); b.Property(x => x.Price).HasPrecision(18, 2); } }
